package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Map;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Closes the period, fixing its due-total and each person's due-total in it as they are now: the figures of the claims that count whose
 *  date falls in it, skipping n/a. Refused when there is no such period or it is already closed. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("periodName") String periodName,
            PeriodStore store, RollupService rollups, Out<PeriodResponse> closed) throws InvalidSheetException {
        String sheet = sheetId.trim();
        PeriodResponse period = store.find(sheet, periodName.trim());
        if (period == null) {
            throw new InvalidSheetException("No such period: " + periodName.trim());
        }
        if (period.closed()) {
            throw new InvalidSheetException("The period " + period.name() + " is already closed");
        }
        LocalDate from = LocalDate.parse(period.from());
        LocalDate to = LocalDate.parse(period.to());
        Map<Long, BigDecimal> people = rollups.dueBetweenByPerson(sheet, from, to);
        BigDecimal total = people.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        if (!store.close(sheet, period.name(), total)) {
            throw new InvalidSheetException("The period " + period.name() + " is already closed");
        }
        store.fixPersonTotals(sheet, period.name(), people);
        closed.set(PeriodResponse.of(period.name(), from, to, true, total, people));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds the claim, due by its date plus the terms of its person's grade in force on that date (else the
 *  sheet's terms in force then), fixed now, and logs it as DRAFT by the user at its due then. */
public class SaveClaimAdded {
    public void save(@Val ClaimInput input, @Val Person person, ClaimStore store, SettingStore settings,
            ClaimLogStore log, Out<Claim> claim) {
        claim.set(add(input, person, store, settings, log));
    }

    static Claim add(ClaimInput input, Person person, ClaimStore store, SettingStore settings, ClaimLogStore log) {
        int terms = settings.terms(person.getSheetId(), person.gradeOn(input.date()), input.date());
        Claim added = store.add(person.getSheetId(), person.getId(), input.amount(), input.date(), input.note(),
                input.corrects(), input.date().plusDays(terms));
        log.record(added, input.user());
        return added;
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';
import { type Claim, counts, live } from '../claims/claims';
import type { Person } from '../people/people';
import { type Floor, type Late, type Rate, claimDue, dueTotal } from '../rates/rates';

/** A period: its name (unique on the sheet), its from and to dates (yyyy-MM-dd, inclusive), whether
 *  it is closed and, once closed, the due-total fixed on closing (null while open) and each person's
 *  due-total fixed on closing, by person id (empty while open). No two periods on a sheet overlap. */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  total: string | null;
  people: Record<string, string>;
};

/** Under the sheet's key, so loading the sheet again re-reads its periods. */
export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;

/** Every period on the sheet, by from-date. */
export function usePeriods(sheet: string) {
  return useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: sheet !== '',
  });
}

/** Whether the date (yyyy-MM-dd) falls in the period. */
export const contains = (period: Period, date: string) => period.from <= date && date <= period.to;

/** The period whose dates contain the date, or undefined when none does. */
export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
  return (periods ?? []).find((p) => contains(p, date));
}

/** A person's due-total for a period: once closed, the figure fixed on closing (0.00 for a person
 *  added since); else the sum of the figures of their claims that count whose date falls in it,
 *  skipping n/a. */
export function personPeriodDue(
  period: Period,
  person: Person,
  claims: Claim[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  if (period.closed) return period.people?.[String(person.id)] ?? '0.00';
  return dueTotal(
    live((claims ?? []).filter((c) => c.personId === person.id), [person])
      .filter((c) => counts(c) && contains(period, c.date))
      .map((c) => claimDue(c, rates, person.grades, floor, late)),
  );
}

/** A period's due-total as the list shows it: the sum of the people's due-totals for it. */
export function periodDue(
  period: Period,
  claims: Claim[] | undefined,
  people: Person[] | undefined,
  rates: Rate[] | undefined,
  floor: Floor,
  late: Late,
): string {
  return dueTotal((people ?? []).map((p) => personPeriodDue(period, p, claims, rates, floor, late)));
}
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { type Person } from '../people/people';
import { useCurrentSheet } from '../../session/session';
import { useSheetToday } from '../sheet/sheet';
import { useClaims } from '../claims/claims';
import { useRates } from '../rates/rates';
import { floorOf, useSettings } from '../settings/settings';
import { lateOf } from '../overdue/overdue';
import { personPeriodDue, usePeriods } from './periods';

// For every period on the sheet, a person's due-total for it: live while the period is open, fixed
// when it was closed.
function PeriodHeads() {
  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <th key={p.name}>{p.name} due</th>
      ))}
    </>
  );
}

function PersonPeriods({ person }: { person: Person }) {
  const [sheet] = useCurrentSheet();
  const periods = usePeriods(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const late = lateOf(settings, today);
  return (
    <>
      {(periods.data ?? []).map((p) => (
        <td key={p.name} data-testid={`person-period-${p.name}-due-total`}>
          {personPeriodDue(p, person, claims.data, rates.data, floorOf(settings), late)}
        </td>
      ))}
    </>
  );
}

export const contributions = [
  PersonColumnHeads.fill({ order: 16, Component: PeriodHeads }),
  PersonColumns.fill({ order: 16, Component: PersonPeriods }),
];
